import sys

def min_split_diff(S: int) -> int:
    # 均分后的两部分异或即为最小分裂差异值
    return (S // 2) ^ ((S + 1) // 2)

def main() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    out = []
    for i in range(1, n + 1):
        S = int(data[i])
        out.append(str(min_split_diff(S)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
```

